import{_ as t,o as e,c as o,Q as a}from"./chunks/framework.b67c47e6.js";const r="/assets/quality-control-page.bd7b6e35.svg",g=JSON.parse('{"title":"Quality Control Report","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/quality_control/index.md","filePath":"guide/reports/quality_control/index.md","lastUpdated":1790346505000}'),s={name:"guide/reports/quality_control/index.md"},n=a('<h1 id="quality-control-report" tabindex="-1">Quality Control Report <a class="header-anchor" href="#quality-control-report" aria-label="Permalink to &quot;Quality Control Report&quot;">​</a></h1><p>The Quality Control Report generates a PDF summarizing the quality control records of your assemblies.</p><p><img src="'+r+'" alt="A page of the Quality Control Report"></p><ol><li>The checklist of each station, with who ticked each task and when, and the form values.</li><li>The pictures, each with who uploaded it.</li><li>The quality control issues of the assembly.</li></ol><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> PDF</li><li><strong>Content:</strong> One section per assembly, with its production checklist (every task, per station, with its pictures and form values) followed by the quality control issues logged for it. An assembly with no checklist says so, and an assembly with no quality control issues says <em>no issue registered</em>.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This report is available both at <strong>project level</strong> and <strong>company level</strong>. In both cases you select the assemblies to include.</p><ul><li><strong>Project level</strong> — Select the assemblies from the project tree.</li><li><strong>Company level</strong> — If your company works by date, pick a production line and a date range to narrow the list, then select the assemblies.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Table style</strong></td><td>How the checklist is printed: classic tables (the default), compact tables, or one table per station.</td></tr><tr><td><strong>Contact person</strong></td><td>Printed on the document. Leave it empty to use the company default.</td></tr><tr><td><strong>Delivery address</strong></td><td>Printed on the document. Leave it empty to use the company default.</td></tr><tr><td><strong>Production line</strong></td><td>Narrows the assemblies you can select (company-level reports).</td></tr><tr><td><strong>Date range</strong></td><td>Narrows the assemblies you can select (company-level reports).</td></tr></tbody></table><h2 id="who-did-what" tabindex="-1">Who did what <a class="header-anchor" href="#who-did-what" aria-label="Permalink to &quot;Who did what&quot;">​</a></h2><p>Every checklist item in the report says <strong>who ticked it</strong>, and every picture says <strong>who uploaded it and when</strong>. The two are separate on purpose: the person who takes the photo is often not the one who ticks the box.</p><p>The name is the <strong>alias</strong> of the employees who were working under the account at that moment. When nobody was named — an older record, or an account with no employees selected — the account name is shown instead. A picture uploaded before this was recorded shows no name in the report, rather than borrowing the name of whoever ticked the task.</p><p>The same information is on the panel itself, in the <strong>Production Proof</strong> card of the constructible detail page, where such a picture says <em>No author recorded</em>.</p><p>See: <a href="/guide/viewer/#who-is-working">Who is working</a> for how employees are selected on the shop floor.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Use this report for quality audits, compliance reviews, and tracking quality trends across your production.</p>',18),i=[n];function l(h,d,c,p,u,m){return e(),o("div",null,i)}const w=t(s,[["render",l]]);export{g as __pageData,w as default};
